UPDATE course_lessons SET content = REPLACE(
  REPLACE(content,
    '### F64 Drive Overtemp',
    '### F64 Drive Overload (F008 is Heatsink OvrTemp)'
  ),
  'The F64 fault indicates the drive''s internal heatsink temperature has exceeded its safe operating limit (typically around 85°C to 100°C depending on the frame size).',
  'The F064 fault indicates the drive has exceeded its current overload capacity (150% for 60 seconds or 200% for 3 seconds). *Note: For heatsink over-temperature, look for fault F008 (Heatsink OvrTemp).* The diagnostic steps below apply to both thermal and overload conditions:'
) WHERE id = 4;

